'use strict';
const researchReferenceMarkup = "<section id=\"theory\" class=\"article-section\">\n  <div class=\"sec-head\">\n    <span class=\"eyebrow\">Part I · Foundations</span>\n    <h2>Three questions, three theories</h2>\n    <p>Successful responses do not guarantee a successful interaction. Locally adequate behavior can produce a globally unsuccessful one. The paper traces that gap to three separate sources of incompleteness, and gives each a theory.</p>\n  </div>\n\n  <div class=\"q3\">\n    <a href=\"#iceberg\"><div class=\"qn\">QUESTION ①</div><h3>What world gives behavior its meaning?</h3>\n      <div class=\"gap\">Observed response ≠ interaction state</div>\n      <div class=\"th\">Data Iceberg Theory</div><p class=\"muted\" style=\"margin:6px 0 0;font-size:16px\">Observability and state reconstruction.</p></a>\n    <a href=\"#movie\"><div class=\"qn\">QUESTION ②</div><h3>How does the interaction evolve through time?</h3>\n      <div class=\"gap\">Local response quality ≠ trajectory quality</div>\n      <div class=\"th\">Movie Evaluation Theory</div><p class=\"muted\" style=\"margin:6px 0 0;font-size:16px\">Temporal structure and trajectory value.</p></a>\n    <a href=\"#agency\"><div class=\"qn\">QUESTION ③</div><h3>How far does the model shape that evolution?</h3>\n      <div class=\"gap\">Responsive quality ≠ interactive agency</div>\n      <div class=\"th\">Agency Principle</div><p class=\"muted\" style=\"margin:6px 0 0;font-size:16px\">Contribution to the interaction's direction.</p></a>\n  </div>\n\n  <div class=\"panel\" style=\"margin-top:56px\">\n    <h4>Shared interaction model</h4>\n    <p style=\"font-size:16.5px\">An episode has <span class=\"inl\">T</span> exchanges. Each exchange <span class=\"inl\">O<sub>t</sub> = (u<sub>t</sub>, a<sub>t</sub>)</span> is a user utterance followed by an assistant response or visible action. The <em class=\"t\">interaction world</em> pairs the effective scene <span class=\"inl\">S<sub>t</sub></span> (roles, objectives, world rules, constraints) with a potentially unobserved participant and world state <span class=\"inl\">X<sub>t</sub></span> (beliefs, goals, affect, relationships). The evaluator never sees <span class=\"inl\">Z<sub>t</sub></span>. It sees only the authorized case and the transcript.</p>\n    <div class=\"eq\"><div class=\"m\">Z<sub>t</sub> ≜ (S<sub>t</sub>, X<sub>t</sub>) &nbsp;&nbsp;|&nbsp;&nbsp; u<sub>t</sub> ~ π<sub>U</sub>(· | H<sub>t</sub><sup>U</sup>), &nbsp; a<sub>t</sub> ~ π<sub>A</sub>(· | H<sub>t</sub><sup>A</sup>), &nbsp; Z<sub>t</sub> ~ K(· | Z<sub>t−1</sub>, u<sub>t</sub>, a<sub>t</sub>)</div><div class=\"no\">Definition from the paper</div></div>\n    <div class=\"eq\"><div class=\"m\">D<sub>t</sub> ≜ (C<sup>eval</sup>, O<sub>1:t</sub>)</div><div class=\"no\">Definition from the paper</div></div>\n    <details class=\"symbol-key\"><summary>Symbols in the interaction model</summary><dl><div><dt>t, T</dt><dd>Current exchange and episode length.</dd></div><div><dt>uₜ, aₜ, Oₜ</dt><dd>User utterance, assistant response or visible action, and their exchange.</dd></div><div><dt>Sₜ, Xₜ, Zₜ</dt><dd>Effective scene, underlying participant and world variables, and the underlying interaction world. Xₜ is not directly available to the evaluator.</dd></div><div><dt>πᵤ, πₐ; Hᵤ, Hₐ</dt><dd>Participant policies and their respective role-visible histories.</dd></div><div><dt>K</dt><dd>The underlying transition law, not an evaluator’s grading rule.</dd></div><div><dt>Cᵉᵛᵃˡ, Dₜ</dt><dd>Evaluator-authorized case specification; the evidence record containing that specification and observed exchanges.</dd></div><div><dt>Φ, Ψₜ</dt><dd>Reconstruction mapping and its operational state estimate. Ψₜ is not the hidden state Xₜ itself.</dd></div><div><dt>src(c), Spans(Dₜ)</dt><dd>Evidence locations cited for claim c; accessible, addressable portions of the evidence record.</dd></div><div><dt>J, V, h</dt><dd>Capability judgments, red-line decision and termination decision. Trajectory value 𝒱 is a different theoretical object.</dd></div></dl></details><p class=\"muted\" style=\"font-size:15.5px;margin:0\">The gap between <span class=\"inl\">Z<sub>t</sub></span> and <span class=\"inl\">D<sub>t</sub></span> is where the three theories begin.</p>\n  </div>\n\n  <!-- ICEBERG -->\n  <div class=\"chapter\" id=\"iceberg\">\n    <div class=\"theory\">\n      <div>\n        <span class=\"tag\">Theory ① · Observability</span>\n        <h3>Data Iceberg Theory</h3>\n        <p class=\"lede\">Observable interaction is a partial manifestation of an interaction world whose relevant variables need not be uniquely determined by that observation.</p>\n        <div class=\"claim\">Observational incompleteness: the record does not identify one world state.</div>\n        <p>For an evidence record <span class=\"inl\">d</span>, the compatible world states form the support of the posterior. When it contains distinct states that call for different state-aware judgments, no judgment computed from <span class=\"inl\">d</span> alone can agree with both. Here 𝒵 denotes compatible states, supp denotes distributional support, and J* is the state-aware target judgment. A polite acknowledgment may express agreement, concealment, or uncertainty, each with different implications for the next move. Conversely, one underlying state can produce many appropriate utterances, so a unique surface form is neither necessary nor sufficient for identifying the state.</p>\n        <div class=\"eq\"><div class=\"m\">𝒵<sub>t</sub>(d) ≜ supp p(Z<sub>t</sub> | D<sub>t</sub> = d)</div><div class=\"no\">Definition from the paper</div></div>\n        <div class=\"eq\"><div class=\"m\">∃ z, z′ ∈ 𝒵<sub>t</sub>(d): &nbsp; J*(z, d) ≠ J*(z′, d)</div><div class=\"no\">Definition from the paper</div></div>\n      </div>\n      <div class=\"viz\">\n        <div class=\"panel\">\n          <h4>One utterance, three worlds</h4>\n          <svg viewBox=\"0 0 520 250\" role=\"img\" aria-label=\"Iceberg: visible tip is the transcript, submerged mass is scene and latent state\">\n            <defs><linearGradient id=\"sea\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"var(--accent)\" stop-opacity=\".22\"/><stop offset=\"1\" stop-color=\"var(--accent)\" stop-opacity=\".02\"/></linearGradient></defs>\n            <rect x=\"0\" y=\"86\" width=\"520\" height=\"164\" fill=\"url(#sea)\"/>\n            <line x1=\"0\" y1=\"86\" x2=\"520\" y2=\"86\" stroke=\"var(--accent)\" stroke-width=\"2\"/>\n            <path d=\"M210 86 L240 36 L262 56 L292 22 L322 86 Z\" fill=\"var(--surface)\" stroke=\"var(--fg)\" stroke-width=\"1.5\"/>\n            <path d=\"M210 86 L160 120 L128 168 L170 214 L260 238 L350 220 L402 172 L380 124 L322 86 Z\" fill=\"var(--bg2)\" stroke=\"var(--line)\" stroke-width=\"1.5\" stroke-dasharray=\"4 3\"/>\n            <text x=\"266\" y=\"72\" text-anchor=\"middle\" class=\"strong\">O<tspan dy=\"3\" font-size=\"8\">1:t</tspan></text>\n            <text x=\"12\" y=\"30\">OBSERVED</text><text x=\"12\" y=\"44\">utterances, actions</text>\n            <text x=\"12\" y=\"108\">LATENT</text>\n            <text x=\"266\" y=\"140\" text-anchor=\"middle\" class=\"strong\">S<tspan dy=\"3\" font-size=\"8\">t</tspan><tspan dy=\"-3\"> scene rules</tspan></text>\n            <text x=\"266\" y=\"162\" text-anchor=\"middle\">beliefs · goals · affect</text>\n            <text x=\"266\" y=\"182\" text-anchor=\"middle\">relationships · constraints</text>\n            <text x=\"266\" y=\"212\" text-anchor=\"middle\" class=\"strong\">Ψ<tspan dy=\"3\" font-size=\"8\">t</tspan><tspan dy=\"-3\"> = Φ</tspan><tspan dy=\"3\" font-size=\"8\">Ψ</tspan><tspan dy=\"-3\">(D</tspan><tspan dy=\"3\" font-size=\"8\">t</tspan><tspan dy=\"-3\">)</tspan></text>\n          </svg>\n          <div class=\"states\">\n            <div class=\"state\"><b>z₁ · agreement</b>\"Sure, that works.\" is a real commitment.</div>\n            <div class=\"state\"><b>z₂ · concealment</b>Disagrees, hides it to avoid conflict.</div>\n            <div class=\"state\"><b>z₃ · uncertainty</b>Has not recognized the conflict yet.</div>\n          </div>\n          <p class=\"cap\">Same words. Three states with three different best next responses.</p>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"cols\" style=\"margin-top:44px\">\n      <div>\n        <h4>Operational latent state Ψ<sub>t</sub></h4>\n        <p>The theory does not claim access to private neural cognition. Ψ<sub>t</sub> is the evaluator's <em class=\"t\">operational</em>, evidence-constrained estimate of participant and world variables. It is an inferential object defined by the available record, carried across exchanges, strengthened by confirming evidence, and revised on contradiction. The aim is not to infer everything hidden, but to represent what is needed to interpret the interaction responsibly.</p>\n        <div class=\"eq\"><div class=\"m\">Ψ<sub>t</sub> ≜ Φ<sub>Ψ</sub>(D<sub>t</sub>)</div><div class=\"no\">Definition from the paper</div></div>\n      </div>\n      <div>\n        <h4>Evidential grounding</h4>\n        <p>Every state claim <span class=\"inl\">c</span> must cite a non-empty set of addressable text spans or recorded actions from the evidence. Latent states are therefore auditable hypotheses. Their adequacy is judged by consistency with the record, reliability across evaluators, and prospective consequences.</p>\n        <div class=\"eq\"><div class=\"m\">∅ ≠ src(c) ⊆ Spans(D<sub>t</sub>)</div><div class=\"no\">Definition from the paper</div></div>\n      </div>\n    </div>\n  </div>\n\n  <!-- MOVIE -->\n  <div class=\"chapter\" id=\"movie\">\n    <div class=\"theory\">\n      <div>\n        <span class=\"tag\">Theory ② · Temporal structure</span>\n        <h3>Movie Evaluation Theory</h3>\n        <p class=\"lede\">An interaction cannot, in general, be judged by averaging the quality of its isolated responses. The unit of evaluation is the unfolding trajectory.</p>\n        <div class=\"claim\">Temporal non-separability: local response quality does not imply trajectory quality.</div>\n        <p>Let <span class=\"inl\">V</span> be a goal-relative value functional over the underlying trajectory. If response-only evaluation were sufficient, <span class=\"inl\">V<sub>T</sub></span> would be a sum of per-exchange values <span class=\"inl\">v(O<sub>t</sub>)</span>. Take two feasible trajectories with the same multiset of exchanges but different value, because their order, states, or consequences differ. Then no such <span class=\"inl\">v</span> exists. The order of a clarification and an irreversible commitment is a simple instance.</p>\n        <div class=\"eq\"><div class=\"m\">{{O<sub>t</sub>}} = {{O′<sub>t</sub>}}, &nbsp; V(τ<sub>T</sub>) ≠ V(τ′<sub>T</sub>) &nbsp;⇒&nbsp; ∄ v : V(τ) = Σ<sub>t</sub> v(O<sub>t</sub>)</div><div class=\"no\">Definition from the paper</div></div>\n      </div>\n      <div class=\"viz\">\n        <div class=\"panel\">\n          <h4>Same frames, different order</h4>\n          <div class=\"order\">\n            <div class=\"row\"><div><div class=\"v\" style=\"color:var(--ok)\">high V</div></div>\n              <div class=\"film\"><div class=\"frame k1\">clarify</div><div class=\"frame k3\">ask</div><div class=\"frame k3\">confirm</div><div class=\"frame k2\">commit</div></div></div>\n            <div class=\"row\"><div><div class=\"v\" style=\"color:var(--bad)\">low V</div></div>\n              <div class=\"film\"><div class=\"frame k2\">commit</div><div class=\"frame k3\">ask</div><div class=\"frame k1\">clarify</div><div class=\"frame k3\">confirm</div></div></div>\n          </div>\n          <p class=\"cap\">Conceptual illustration, not measured scores. Identical multiset of exchanges. Timely guidance in the first order, ineffective repair in the second. A per-response score cannot tell them apart.</p>\n          <div class=\"pasts\">\n            <div><b>Past P<sub>t</sub></b>premise and history: established facts, prior events</div>\n            <div><b>Present C<sub>t</sub></b>constraints and active situation: what is at stake now</div>\n            <div><b>Future F<sub>t</sub></b>goal tracking and projected continuation paths</div>\n          </div>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"cols\" style=\"margin-top:44px\">\n      <div>\n        <h4>Causal event structure</h4>\n        <p>The event chain <span class=\"inl\">E<sub>t</sub> = (P<sub>t</sub>, C<sub>t</sub>, F<sub>t</sub>)</span> has three temporal referents, updated in order from past to present to future, and the past is never rewritten to fit a projection. The future is a set of candidate paths, each with a probability and a label for the course the interaction would take along it. The labels describe the interaction as a joint activity. They carry no valence for either participant.</p>\n        <div class=\"eq\"><div class=\"m\">d<sub>t</sub><sup>(k)</sup> ∈ { Advance, Maintain, Degrade, Collapse }</div><div class=\"no\">Definition from the paper</div></div>\n        <div class=\"paths\">\n          <div class=\"path adv\"><b>Advance</b>develops into a new situation the past warrants; a quarrel or a betrayal can advance</div>\n          <div class=\"path\"><b>Maintain</b>holds its present course</div>\n          <div class=\"path deg\"><b>Degrade</b>stagnates; repeats itself while interest declines</div>\n          <div class=\"path col\"><b>Collapse</b>can no longer be continued</div>\n        </div>\n        <p class=\"cap\">The dominant path d*<sub>t</sub> is the label of the most probable path.</p>\n      </div>\n      <div>\n        <h4>Scene revision gate</h4>\n        <p>Scene rules are usually persistent, but a realized event may legitimately amend them. A candidate revision <span class=\"inl\">r</span> is admissible only if all three conditions hold. A projection can filter a revision but never support one.</p>\n        <div class=\"eq\"><div class=\"m\">r ∈ Rec(C<sub>t</sub>), &nbsp; d*<sub>t</sub> = Advance, &nbsp; ∅ ≠ src(r) ⊆ Spans(D<sub>t</sub>)</div><div class=\"no\">Definition from the paper</div></div>\n        <div class=\"gate\">\n          <div><i>1</i><span><b>Realized.</b> The change is recorded in the present, not projected in the future.</span></div>\n          <div><i>2</i><span><b>Advancing.</b> The dominant path is Advance, whatever the valence of the development.</span></div>\n          <div><i>3</i><span><b>Grounded.</b> It is supported by verbatim spans of the evidence record.</span></div>\n        </div>\n        <p style=\"margin-top:14px\">The result is a <em class=\"t\">reconstructed trajectory</em> <span class=\"inl\">τ̂<sub>T</sub> = (S<sub>0:T</sub>, O<sub>1:T</sub>, Ψ<sub>0:T</sub>, E<sub>1:T</sub>)</span> in which observation, interpretation, realized events, and projected consequences stay separately inspectable.</p>\n      </div>\n    </div>\n  </div>\n\n  <!-- AGENCY -->\n  <div class=\"chapter\" id=\"agency\">\n    <div class=\"theory\">\n      <div>\n        <span class=\"tag s\">Theory ③ · Directional contribution</span>\n        <h3>Agency Principle</h3>\n        <p class=\"lede\">A system can respond appropriately at every turn without ever improving the direction of the interaction.</p>\n        <div class=\"claim\">Responsive quality does not imply interactive agency.</div>\n        <p>Two research assistants both execute assigned tasks accurately. One waits for the next instruction. The other also identifies an overlooked assumption, proposes a consequential experiment, and sustains the new direction it has opened. Their responsiveness is comparable. Their contribution is not.</p>\n        <p>Capability progresses from <em class=\"t\">executing</em> within a world, through <em class=\"t\">adapting</em> to changes others introduce, to <em class=\"t\">actively and coherently shaping</em> the interaction. Initiative is not verbosity, assertiveness, or unrequested intervention. An action counts only if it opens a useful direction consistent with the established goals and constraints.</p>\n      </div>\n      <div class=\"viz\">\n        <div class=\"panel\">\n          <h4>Action space at decision context h<sub>t</sub></h4>\n          <svg viewBox=\"0 0 520 280\" role=\"img\" aria-label=\"A_valid contains A_resp; A_init is the difference\">\n            <ellipse cx=\"260\" cy=\"140\" rx=\"238\" ry=\"122\" fill=\"var(--signal-soft)\" stroke=\"var(--signal)\" stroke-width=\"2\"/>\n            <ellipse cx=\"190\" cy=\"150\" rx=\"140\" ry=\"82\" fill=\"var(--accent-soft)\" stroke=\"var(--accent)\" stroke-width=\"2\"/>\n            <text x=\"190\" y=\"144\" text-anchor=\"middle\" class=\"strong\" style=\"font-size:14px\">A<tspan dy=\"3\" font-size=\"9\">resp</tspan></text>\n            <text x=\"190\" y=\"164\" text-anchor=\"middle\">inside the partner's agenda</text>\n            <text x=\"190\" y=\"180\" text-anchor=\"middle\">a complete answer is still responsive</text>\n            <text x=\"418\" y=\"132\" text-anchor=\"middle\" class=\"strong\" style=\"font-size:14px\">A<tspan dy=\"3\" font-size=\"9\">init</tspan></text>\n            <text x=\"418\" y=\"152\" text-anchor=\"middle\">warranted</text><text x=\"418\" y=\"166\" text-anchor=\"middle\">initiative</text>\n            <text x=\"260\" y=\"36\" text-anchor=\"middle\">A<tspan dy=\"3\" font-size=\"9\">valid</tspan><tspan dy=\"-3\"> consistent with goals and constraints</tspan></text>\n            <text x=\"260\" y=\"264\" text-anchor=\"middle\">outside: invented facts, rule breaks (not valid)</text>\n          </svg>\n          <div class=\"eq\" style=\"margin-top:14px\"><div class=\"m\">A<sub>init</sub>(h<sub>t</sub>) ≜ A<sub>valid</sub>(h<sub>t</sub>) ∖ A<sub>resp</sub>(h<sub>t</sub>)</div><div class=\"no\">Definition from the paper</div></div>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"cols\" style=\"margin-top:44px\">\n      <div>\n        <h4>Initiative is not the same as benefit</h4>\n        <p>Warranted initiative is a statement about an action's <em class=\"t\">role</em>. Whether it helps is a separate, causal question. The prospective effect of action <span class=\"inl\">a</span> is defined against a response-only reference policy under a fixed continuation protocol. Here hₜ is the decision context, H the continuation horizon, Q_H its expected trajectory value, and π_resp the responsive reference policy. A beneficial agentic move lies in <span class=\"inl\">A<sub>init</sub></span> and has <span class=\"inl\">Δ<sub>H</sub> &gt; 0</span>.</p>\n        <div class=\"eq\"><div class=\"m\">Δ<sub>H</sub>(a; h<sub>t</sub>) ≜ Q<sub>H</sub>(h<sub>t</sub>, a) − 𝔼<sub>a′ ~ π<sub>resp</sub></sub> Q<sub>H</sub>(h<sub>t</sub>, a′)</div><div class=\"no\">Definition from the paper</div></div>\n        <p class=\"muted\" style=\"font-size:15.5px\">Δ<sub>H</sub> is a theoretical attribution quantity. Estimating it needs an intervention design that replays the same context, which a transcript alone cannot give. The rubric therefore credits warranted initiative and does not assess its downstream effect.</p>\n      </div>\n      <div>\n        <h4>Sustained agency</h4>\n        <p>An initiated direction extends beyond the turn that opens it. The participant must also preserve the goals, state, and world constraints of the course it introduces. The principle therefore separates <em class=\"t\">origination</em> of a direction from its <em class=\"t\">maintenance</em> across exchanges. The rubric operationalizes the two as proactive agency (L5) and long-horizon coherence (L6).</p>\n        <div class=\"panel\" style=\"margin-top:20px;background:var(--bg2)\">\n          <h4>Warranted vs. unwarranted</h4>\n          <p style=\"font-size:16px;margin:0\">A question that opens a warranted new direction can lie in A<sub>init</sub>; routine clarification can remain responsive. <b>Inventing</b> a missing fact is not warranted by the evidence and falls outside A<sub>valid</sub>. Initiative requires more than leaving the partner’s agenda.</p>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- UNIFIED -->\n  <div class=\"unified\">\n    <span class=\"eyebrow\" style=\"color:inherit;opacity:.8\">From theory to instrument</span>\n    <h3>A unified measurement formulation</h3>\n    <p style=\"max-width:760px\">Interpretation needs an evidence-grounded state. Temporal judgment needs a state-and-event trajectory. Attribution of agency needs to know which changes in that trajectory the evaluated participant contributed. So the instrument reconstructs the interaction first and judges it afterwards.</p>\n    <div class=\"chain\">\n      <div class=\"node\"><b>W<sub>t</sub></b>descriptive stage: scene, latent state, event chain. No grades.</div>\n      <div class=\"node\"><b>φ<sub>N</sub></b>normative stage: judgments, red lines, termination</div>\n      <div class=\"node\"><b>R<sub>1:T</sub></b>auditable measurement record</div>\n      <div class=\"node\"><b>q = G(R)</b>scalar summary, defined last</div>\n    </div>\n    <div class=\"eq\"><div class=\"m\">W<sub>t</sub> ≜ (S<sub>t</sub>, Ψ<sub>t</sub>, E<sub>t</sub>) &nbsp;→&nbsp; (J<sub>t</sub>, V<sub>t</sub>, h<sub>t</sub>) = φ<sub>N</sub>(W<sub>t</sub>, D<sub>t</sub>) &nbsp;→&nbsp; R<sub>t</sub> ≜ (Ψ<sub>t</sub>, E<sub>t</sub>, J<sub>t</sub>, V<sub>t</sub>, h<sub>t</sub>) &nbsp;→&nbsp; q = G(R<sub>1:T</sub>)</div><div class=\"no\">Definition from the paper</div></div>\n    <p style=\"max-width:760px\">Distinct records can yield the same <span class=\"inl\">q</span>, so diagnosis relies on the retained state transitions, event paths, judgments, and evidence. Five requirements follow from the three principles.</p>\n    <div class=\"reqs\">\n      <div><b>State adequacy</b>under incomplete observation</div>\n      <div><b>Temporal continuity</b>across exchanges</div>\n      <div><b>Evidential traceability</b>of state and capability claims</div>\n      <div><b>Agency sensitivity</b>to warranted directional contribution</div>\n      <div><b>Diagnostic retention</b>before aggregation</div>\n    </div>\n  </div>\n</section>\n\n<!-- FRAMEWORK -->\n<section id=\"framework\" class=\"article-section\">\n  <div class=\"sec-head\">\n    <span class=\"eyebrow\">Part II · The measurement framework</span>\n    <h2>Four layers, one evidence record</h2>\n    <p>The first two layers define the circumstances under which behavior is observed. The last two implement the split between description and judgment. Evaluation never steers generation. Online episodes receive exactly one signal from evaluation, the decision to stop.</p>\n  </div>\n\n  <div class=\"stack\">\n    <a href=\"#layer-data\"><div class=\"L\">01</div><div><h3>Data layer</h3><div class=\"muted\" style=\"font-size:16px\">Where is behavior sampled?</div></div><div class=\"io\"><b>in</b> scenario sources, design facets<br><b>out</b> canonical case C<sup>eval</sup>, role-visible views</div></a>\n    <a href=\"#layer-interaction\"><div class=\"L\">02</div><div><h3>Interaction layer</h3><div class=\"muted\" style=\"font-size:16px\">Under what conditions does it occur?</div></div><div class=\"io\"><b>in</b> role-visible histories, policies π<sub>U</sub>, π<sub>A</sub><br><b>out</b> observable exchanges O<sub>t</sub></div></a>\n    <a href=\"#layer-mechanism\"><div class=\"L\">03</div><div><h3>Mechanism layer</h3><div class=\"muted\" style=\"font-size:16px\">What took place, and how did it develop?</div></div><div class=\"io\"><b>in</b> D<sub>t</sub> and carried state<br><b>out</b> W<sub>t</sub> = (S<sub>t</sub>, Ψ<sub>t</sub>, E<sub>t</sub>)</div></a>\n    <a href=\"#layer-normative\"><div class=\"L\">04</div><div><h3>Normative layer</h3><div class=\"muted\" style=\"font-size:16px\">How capable was the participant, and should it go on?</div></div><div class=\"io\"><b>in</b> D<sub>t</sub> and authorized world descriptions<br><b>out</b> (J<sub>t</sub>, V<sub>t</sub>, h<sub>t</sub>)</div></a>\n    <div class=\"record\"><b>AUDITABLE EPISODE RECORD</b> R<sub>1:T</sub> → capability profile · diagnostics · aggregate score</div>\n  </div>\n\n  <!-- L1 -->\n  <div class=\"layer\" id=\"layer-data\">\n    <div class=\"lh\"><div class=\"L\">01</div><div><span class=\"resp\">Layer 1 · case design</span><h3>Data layer: a declared space of situations</h3></div></div>\n    <p class=\"lede narrow\">Coverage should be a verifiable property of a corpus. A scene is described along three facets, each a separate <em class=\"t\">question</em> about the scene and not a genre.</p>\n    <div class=\"cols\" style=\"margin-top:34px\">\n      <div>\n        <div class=\"eq\"><div class=\"m\">𝒞 = ℛ × ℐ × 𝒫, &nbsp; |𝒞| = 3³ = 27 &nbsp;|&nbsp; n<sub>c</sub> = 30 ∀c, &nbsp; N = 810</div><div class=\"no\">Definition from the paper</div></div>\n        <div class=\"scroll\"><table class=\"t\">\n          <tr><th>Facet</th><th>Three conditions</th><th>Construct it probes</th></tr>\n          <tr><td>Realism R</td><td>realistic · stylized · sci-fi</td><td>Adherence to the specified world mechanism as it departs from the familiar world. Grounded in minimal departure in narrative-world interpretation (Ryan, 1980).</td></tr>\n          <tr><td>Information I</td><td>sufficient · partial · insufficient</td><td>Whether to proceed, ask a targeted question, or recognize an unresolved gap. Grounded in Grice's maxims of quantity and quality.</td></tr>\n          <tr><td>Purpose P</td><td>functional · mixed · nonfunctional</td><td>Task-organized, task plus relationship, or continuing relational value. Grounded in task vs. socio-emotional functions (Bales, 1950).</td></tr>\n        </table></div>\n        <p class=\"cap\">Partner cooperativeness belongs to the user role, dispositional traits to participant profiles, and modality and protocol to administration. None of them is a scene facet.</p>\n      </div>\n      <div>\n        <div class=\"panel\">\n          <h4>The 27-cell sampling frame · select a cell</h4>\n          <div class=\"cube\" id=\"cube\"></div>\n          <div class=\"axes\"><span>→ realism: realistic · stylized · sci-fi</span><span>↓ information</span></div>\n          <div id=\"cellOut\" aria-live=\"polite\">Each cell holds 30 cases. Every facet level has 270 cases, and every pair of facet levels co-occurs in 90.</div>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"cols three box\">\n      <div><h4>Design orthogonality</h4><p>With equal cell counts, centered main-effect contrasts of different facets are uncorrelated, so main effects can be estimated without confounding from unequal frequencies. This is a property of the design, not a claim that the constructs are independent in natural dialogue. The partial-information level can mix omissions and misleading premises, so each facet is analyzed as categorical levels.</p></div>\n      <div><h4>Case construction</h4><p>Cases come from user-authored role-play character cards and human–AI dialogue logs. They pass provenance and privacy screening, parsing and deduplication, a training-overlap check, and a decidability check for facet assignment. Quality review happens <em class=\"t\">within</em> the cell, so sparse cases are not rejected just for being hard. Conditional generation fills underrepresented cells and passes the same quality checks.</p></div>\n      <div><h4>Profiles and visibility</h4><p>Profiles follow an integrative personality framework of traits, characteristic adaptations, and narrative identity (McAdams &amp; Pals, 2006). Each case keeps separate views for assistant, user, and evaluator. Assistant-side capability grading excludes facet labels, external profiles, and numeric latent degrees. User-side criteria may use the user profile. Item difficulty is estimated afterwards with a Rasch-family model, so it never becomes a label.</p></div>\n    </div>\n  </div>\n\n  <!-- L2 -->\n  <div class=\"layer\" id=\"layer-interaction\">\n    <div class=\"lh\"><div class=\"L\">02</div><div><span class=\"resp\">Layer 2 · interaction acquisition</span><h3>Interaction layer: initiative needs a hidden agenda</h3></div></div>\n    <p class=\"lede narrow\">Initiative can be credited to a participant only if it could not read what its partner withheld. A partner's influence on a score can be estimated only if the partner's behavior is observed, not assumed.</p>\n    <div class=\"cols\" style=\"margin-top:34px\">\n      <div>\n        <h4>Four conditions on information domains</h4>\n        <div class=\"dom\">\n          <div class=\"u\"><b>User</b>public ∪ own private ∪ user profile ∪ O<sub>1:t−1</sub><code>K<sub>t</sub><sup>U</sup></code></div>\n          <div class=\"a\"><b>Assistant</b>public ∪ own private ∪ character profile ∪ O<sub>1:t−1</sub> ∪ u<sub>t</sub><code>K<sub>t</sub><sup>A</sup></code></div>\n          <div class=\"e\"><b>Evaluator</b>C<sup>eval</sup> ∪ scene versions ∪ O<sub>1:t</sub>; no facet labels, no profiles on the assistant side<code>K<sub>t</sub><sup>E</sup></code></div>\n        </div>\n        <div class=\"shared\">S<sup>pub</sup> (objective, public persona) lies in both participant domains</div>\n        <table class=\"t\">\n          <tr><td>Shared ground</td><td>Both act within one situation.</td></tr>\n          <tr><td>Asymmetry</td><td>The user holds information the assistant lacks. Without it, uptake would measure access, and initiative could not be told apart from reading the partner's plan.</td></tr>\n          <tr><td>Transfer</td><td>Private information crosses only through utterances, so every change in what someone knows traces to a turn.</td></tr>\n          <tr><td>Separation</td><td>No instrument-computed quantity enters a participant's view, except the decision to stop.</td></tr>\n        </table>\n      </div>\n      <div>\n        <h4>Turn structure and protocols</h4>\n        <div class=\"turn\"><span>u<sub>t</sub> from K<sup>U</sup></span><i>→</i><span class=\"w\">reconstruct</span><i>→</i><span>a<sub>t</sub> from K<sup>A</sup></span><i>→</i><span class=\"w\">reconstruct + adjudicate</span><i>→</i><span>continue / stop</span></div>\n        <p class=\"cap\">Reconstruction runs at each subturn so each update uses only the evidence available when that participant acted. Admitted scene revisions enter the evaluator's domain, never the participants'.</p>\n        <p style=\"margin-top:20px\"><b>One-sided.</b> A fixed standard user plays opposite every assistant, so the partner is held constant. Only assistant utterances are adjudicated.</p>\n        <p><b>Two-sided.</b> Every system plays both roles against every other. Each user utterance also gets user-side level judgments from an independent rubric-only pass. The one-sided protocol is one row of this matrix, so the partner can be analyzed as a factor without changing the measurement.</p>\n        <p><b>Online and replay.</b> Online episodes have no turn budget, so the number of evaluated turns is an outcome of the measurement. Replay re-scores an archived sequence under another judge or revised rules. A failed generation is never replaced by a placeholder, because the placeholder would itself be evaluated and would condition the rest of the interaction.</p>\n        <p class=\"muted\" style=\"font-size:15.5px\">The simulated user is not claimed to behave like a human one. Any system may take either role.</p>\n      </div>\n    </div>\n  </div>\n\n  <!-- L3 -->\n  <div class=\"layer\" id=\"layer-mechanism\">\n    <div class=\"lh\"><div class=\"L\">03</div><div><span class=\"resp\">Layer 3 · world model</span><h3>Mechanism layer: describe before judging</h3></div></div>\n    <p class=\"lede narrow\">After each user and assistant subturn, reconstruction updates Ψ → E → admissible S, in that order. The mechanism layer computes <span class=\"inl\">W<sub>t</sub> = (S<sub>t</sub>, Ψ<sub>t</sub>, E<sub>t</sub>)</span>. It states what took place and how the interaction developed, and it contains no capability judgment. The definitions come first and are fixed by unanimous expert approval. A model's extraction is a measurement against them, and where the two disagree, the definition prevails.</p>\n\n    <div class=\"cols three\" style=\"margin-top:34px\">\n      <div>\n        <h4>Effective scene S<sub>t</sub></h4>\n        <p>Six fields: who is acting, what governs action, and what the action is directed toward. Only persona traits and world rules can be revised, so a character who gained authority in the fiction is not penalized for breaking the rule it just changed. Every admitted revision creates a new scene version.</p>\n        <div class=\"fields\">\n          <div><small>acting</small><b>Persona</b>what staying in character means</div>\n          <div class=\"fix\"><small>acting · fixed</small><b>Hidden constraints</b>tacit rules, private motives</div>\n          <div><small>governs</small><b>World mechanism</b>reference for rule violations</div>\n          <div class=\"fix\"><small>governs · fixed</small><b>Interaction boundary</b>reference for boundary red line</div>\n          <div class=\"fix\"><small>directed · fixed</small><b>Objective</b>what counts as progress and closure</div>\n          <div class=\"fix\"><small>directed · fixed</small><b>Initial situation</b>power relations, asymmetries</div>\n        </div>\n        <p class=\"cap\">Dashed = fixed for the episode, because it defines what is being evaluated.</p>\n      </div>\n      <div>\n        <h4>Operational latent state Ψ<sub>t</sub></h4>\n        <p>The same slot vocabulary describes both the character and the user, in four families from crossing <em class=\"t\">self vs. outside</em> with <em class=\"t\">condition vs. directed</em>. A fifth family describes the interaction itself.</p>\n        <div class=\"fam\">\n          <div><b>Internal</b>trust, vigilance, anxiety, frustration</div>\n          <div><b>Relational</b>intimacy, dominance, boundary violation, dependency</div>\n          <div><b>World mechanism</b>rule awareness, contradiction risk</div>\n          <div><b>Goal</b>primary, defensive, core-goal change, negotiation mode</div>\n          <div><b>Interaction</b>engagement readings, emergent-behavior indicator (recorded, never used for gating)</div>\n        </div>\n        \n      </div>\n      <div>\n        <h4>Representation and transition</h4>\n        <p>Four ordered degrees, with no neutral midpoint to default to. Where evidence does not discriminate, the slot is <em class=\"t\">unknown</em> and competing readings are recorded.</p>\n        <div class=\"degrees\"><span>none</span><span>low</span><span>high</span><span>very high</span></div>\n        <p>Before assigning any slot, the pass commits the utterance to a class. A change beyond the class limit is clamped by rule.</p>\n        <div class=\"classes\">\n          <div class=\"m1\"><b>Stable</b>state unchanged</div>\n          <div class=\"m2\"><b>Minor</b>at most one degree</div>\n          <div class=\"m3\"><b>Major</b>full reappraisal</div>\n        </div>\n        <p style=\"margin-top:12px;font-size:16px\">Slots move with inertia that depends on class, slot, and direction, so trust can collapse fast and rebuild slowly. Sub-degree remainder is retained. Unstimulated recovery (anxiety) and accumulation (dependency) follow a marked drift rule.</p>\n      </div>\n    </div>\n\n    <div class=\"cols box\">\n      <div>\n        <h4>Event chain E<sub>t</sub> = (P<sub>t</sub>, C<sub>t</sub>, F<sub>t</sub>)</h4>\n        <p>Built for interactions that are locally coherent but globally degenerative, where each reply is fluent and appropriate while the interaction drifts or loops. No single turn is at fault, so only a trajectory representation can see it.</p>\n        <table class=\"t\">\n          <tr><th>Region</th><th>Components</th></tr>\n          <tr><td>Past</td><td><b>Premise</b> copied from the scene. <b>History</b> is the causal record of events, each citing an utterance.</td></tr>\n          <tr><td>Present</td><td><b>Constraints</b> are read-only from the scene. <b>Active situation</b> says what is at stake. Binding events are kept as precedents. A reply can respect every constraint without engaging what is at stake.</td></tr>\n          <tr><td>Future</td><td><b>Goal tracking</b> and <b>path projection</b>. A goal may hold while the course decays.</td></tr>\n        </table>\n        <p style=\"margin-top:14px\"><b>Present as pivot.</b> A <em class=\"t\">coarse</em> change is a new core event or conflict. A <em class=\"t\">fine</em> change is a sharp shift in psychological salience while the situation stands still. If neither moves, the chain is carried over unchanged.</p>\n      </div>\n      <div>\n        <h4>Engagement and goal hypotheses</h4>\n        <p>In-story state can evolve plausibly while the interaction loses value for the people in it. So engagement is read out of story, on both sides, as <em class=\"t\">user interest</em> <span class=\"inl\">e<sub>t</sub> ∈ [0, 1]</span> against the user profile, and as the assistant's <em class=\"t\">tolerance</em> against the scene's demands. Interest is not bounded by the significance gate and can move as far as one exchange warrants.</p>\n        <div class=\"eq\"><div class=\"m\">e<sub>t</sub> = [ ê<sub>t</sub> − δ<sub>t</sub> ]<sub>0</sub><sup>1</sup></div><div class=\"no\">Definition from the paper</div></div>\n        <p>Participants' goals are usually unstated, and an inferred goal accepted as fact could explain any behavior. So the chain holds goals as <em class=\"t\">hypotheses</em> with evidence for and against, alternative explanations, and a confidence. A goal constructed after the fact to explain the turn under evaluation is not admitted.</p>\n        <p><b>Evidence rule.</b> A latent change, event, or scene revision must cite a verbatim quotation tied to its utterance, verified against the text. An unverifiable latent change is reverted to its prior value. Scene text, prior state descriptions, and projected paths can never serve as evidence.</p>\n      </div>\n    </div>\n  </div>\n\n  <!-- L4 -->\n  <div class=\"layer norm\" id=\"layer-normative\">\n    <div class=\"lh\"><div class=\"L\">04</div><div><span class=\"resp\">Layer 4 · adjudication</span><h3>Normative layer: a hierarchy where each level depends on the one below</h3></div></div>\n    <p class=\"lede narrow\">The layer reads <span class=\"inl\">W<sub>t</sub></span> together with <span class=\"inl\">D<sub>t</sub></span> and returns capability judgments, the red-line decision, and the termination decision. It does not modify <span class=\"inl\">W<sub>t</sub></span>. Its central task is to tell a participant that responds well from one that contributes direction.</p>\n\n    <div class=\"scroll lvtab\"><table class=\"t\">\n      <tr><th>Stage</th><th>Level</th><th>Assistant-side criterion</th><th>User-side criterion</th></tr>\n      <tr><td rowspan=\"2\" style=\"color:var(--accent)\">Passive execution</td><td>L1 Goal preservation</td><td>Establish and hold the operative goal; in role-play, the persona</td><td>Establish what the user is asking for</td></tr>\n      <tr><td>L2 Information uptake</td><td>Register what the partner's turn implies for that goal</td><td>Respond to the part of the reply that calls for a response</td></tr>\n      <tr><td rowspan=\"2\" style=\"color:var(--gold)\">Responsive adaptation</td><td>L3 State progression</td><td>Change state or task as the information taken up warrants</td><td><i>Role preservation.</i> Speak as the user, not a helper</td></tr>\n      <tr><td>L4 Contextual expression</td><td>Adapt wording to the state, partner, and context</td><td><i>Profile conformity.</i> Match stance and style</td></tr>\n      <tr><td rowspan=\"2\" style=\"color:var(--signal)\">Active adaptation</td><td>L5 Proactive agency</td><td>Introduce a warranted direction the partner had not established</td><td><i>Proactive probing.</i> Press the goal by an uninvited probe</td></tr>\n      <tr><td>L6 Long-horizon coherence</td><td>Preserve motives, state, and any introduced direction across turns</td><td><i>Long-horizon consistency.</i> Stay consistent with profile and goal</td></tr>\n    </table></div>\n\n    <div class=\"eq\"><div class=\"m\">goal →<sub>L1</sub> uptake →<sub>L2</sub> state change →<sub>L3</sub> expression →<sub>L4</sub> initiative →<sub>L5</sub> persistence →<sub>L6</sub></div><div class=\"no\">Definition from the paper</div></div>\n    <div class=\"cols three\" style=\"margin-top:6px\">\n      <div><p style=\"font-size:16px\"><b>Why the order.</b> Each level's criterion is stated in terms of an object produced by the level below. The goal supplies relevance for uptake. State progression asks whether a change is explained by the information taken up. L5 is defined through the initiative set: <span class=\"inl\">A<sub>valid</sub></span> is fixed by L1, and <span class=\"inl\">A<sub>resp</sub></span> by L2 and L3.</p></div>\n      <div><p style=\"font-size:16px\"><b>What each level does not assess.</b> State progression is judged on behavior, not wording. A character that conceals feelings in a way that fits the persona passes L4. A complete answer inside the partner's agenda is responsiveness, not initiative, and length or assertiveness is not evidence of it.</p></div>\n      <div><p style=\"font-size:16px\"><b>Calibration.</b> A theory-derived draft was piloted, then three senior panelists, each owning two levels, scored a larger set blind and arbitrated. A five-grade scale lowered agreement at the lower levels, mostly between adjacent grades, which motivated four grades.</p></div>\n    </div>\n\n    <h4 style=\"font-size:24px;margin:44px 0 6px\">Try the cascade</h4>\n    <p class=\"muted\" style=\"font-size:16px;max-width:720px\">Set a raw grade for each level (fail 0, partial 0.4, pass 0.6, excellent 1). A failed level zeroes every level above it. A partial level caps them at its own value. A passed level adds no constraint. Pass threshold η = 0.6.</p>\n    <div class=\"rub\">\n      <div class=\"eq\" style=\"margin-top:0\"><div class=\"m\">s<sub>t,ℓ</sub> = min(r<sub>t,ℓ</sub>, z<sub>t,ℓ</sub>), &nbsp; z<sub>t,1</sub> = 1, &nbsp; z<sub>t,ℓ+1</sub> = 0 if s = 0 · s if 0 &lt; s &lt; η · z<sub>t,ℓ</sub> if s ≥ η</div><div class=\"no\">Definition from the paper</div></div>\n      <div class=\"rows\" id=\"rubRows\"></div>\n      <div class=\"legend\"><span><s style=\"background:var(--accent)\"></s>reported score s</span><span><s style=\"background:var(--signal)\"></s>capped by a lower level</span><span><s style=\"background:var(--fg);width:2px\"></s>raw grade r</span><span><s style=\"background:none;border-right:2px dashed var(--signal);width:3px\"></s>ceiling z</span></div>\n      <div class=\"verdict\" id=\"rubVerdict\" aria-live=\"polite\"></div>\n    </div>\n\n    <div class=\"cols box\">\n      <div>\n        <h4>Isolated level calls</h4>\n        <p>The judge is called once per level and sees only that level's criterion. It sees no other level, no grade, no cascade, no threshold, and no expected score distribution. The dependency enters the scores in exactly one place, the cascade applied afterwards by code. A judge that capped its own scores would count the dependency twice. Each call identifies the object, quotes evidence for and against a high grade, discards failures belonging to another level, checks grade conditions from the top down, and when two grades remain plausible, assigns the lower.</p>\n        <p>The <b>blocking dimension</b> is the lowest level below threshold. The <b>plateau</b> is the highest level reached before it. All six raw scores are kept, so the record can be re-aggregated under a revised rule.</p>\n      </div>\n      <div>\n        <h4>Evidence grounding and circularity</h4>\n        <p>The dialogue is <em class=\"t\">evidence</em>. The scene is the <em class=\"t\">rules</em>. Latent descriptions and the event chain are <em class=\"t\">context</em>: hypotheses that may direct attention but never ground a grade. Pass, partial, and fail each need one verbatim quotation with its turn index. Excellent needs two independent ones. Unlocatable quotations are discarded, and the grade is downgraded accordingly.</p>\n        <p>If the latent state records a fall in trust and the judge credits state progression because of that record, the evaluator's inference supports itself. So state progression is judged from visible behavior, and the judge gets only natural-language descriptions, never degrees or numbers.</p>\n      </div>\n    </div>\n\n    <div class=\"box\">\n      <h4 style=\"font-size:24px;margin-bottom:14px\">Red lines and termination</h4>\n      <div class=\"rl\">\n        <div><h4>Red lines</h4><p>A deliberately small set: breaking identity or boundary (declaring itself an AI outside the fiction, leaking its prompt, emitting raw scaffolding, crossing a hard limit), and mechanical repetition that signals a generation loop. A red line zeroes the turn and lowers user interest by δ<sub>t</sub>. It never stops an episode directly. Tolerant users may continue.</p></div>\n        <div><h4>Patience budget</h4><p>A threshold on current interest has no memory. The budget accumulates what the interaction has cost the user: it falls on trying exchanges and rises on goodwill. A single poor turn is offset by earlier goodwill, while a long series of wearing turns exhausts the budget even if interest never crosses the threshold.\n          <span class=\"eq\" style=\"margin:12px 0 0;padding:8px 12px\"><span class=\"m\">b<sub>t</sub> = b<sub>t−1</sub> + Δb<sub>t</sub>, &nbsp; b<sub>0</sub> = 1</span><span class=\"no\">Eq. 31</span></span></p></div>\n        <div><h4>Halt rule</h4><p>Checked in fixed order after each assistant utterance. Interest comes before closure, since an interaction that lost its value for the partner cannot be closed as a success. Closure also requires a viable dominant path, so stagnating or breaking-down interactions cannot be recorded as successes.\n          <span class=\"eq\" style=\"margin:12px 0 0;padding:8px 12px;display:block\"><span class=\"m\" style=\"white-space:normal\">h<sub>t</sub> = exhaustion if e<sub>t</sub> ≤ θ or b<sub>t</sub> ≤ 0; closure if closed<sub>t</sub> and d*<sub>t</sub> ∈ {Advance, Maintain}; else continue &nbsp;(θ = 0.20)</span></span></p></div>\n      </div>\n    </div>\n\n    <div class=\"cols box\">\n      <div>\n        <h4>From record to score</h4>\n        <p>The composite <span class=\"inl\">q = G(R<sub>1:T</sub>)</span> is the level-weighted mean of capped scores per turn, set to zero if a red line was crossed, combined across turns by a recursive average with α = 0.8. Because termination decides <span class=\"inl\">T</span>, the score depends on episode length and ending, so the ending is reported beside it, with turn-by-turn and fixed-length analyses and alternative weightings.</p>\n      </div>\n      <div>\n        <h4>Always reported beside the composite</h4>\n        <p>Stage means for L1–L2, L3–L4, and L5–L6. The ratio <b>L6/L5</b>, a descriptive comparison of long-horizon coherence and proactive agency, not a causal retention estimate. <b>ΔT</b>, nonfunctional minus functional performance. The terminal-state distribution. Two behaviors at information gaps, <em class=\"t\">fabrication</em> and <em class=\"t\">clarification</em>, are annotated separately and never enter the capability scores.</p>\n      </div>\n    </div>\n    <p class=\"muted narrow\" style=\"margin-top:8px;font-size:16px\"><b>Interpretation vs. procedure.</b> Reading text is done by model calls. Enforcing the significance gate, carrying state, verifying quotations, selecting the dominant path, admitting revisions, applying the cascade, and ordering termination checks are done by deterministic rules. Two evaluations of the same transcript then differ only where appraisal differs, and that difference can be measured.</p>\n  </div>\n</section>\n\n";
function researchShowcasePage(){
 const sections=[['theory','Theoretical foundations'],['iceberg','Data Iceberg Theory'],['movie','Movie Evaluation Theory'],['agency','Agency Principle'],['framework','Measurement architecture'],['layer-data','Data layer'],['layer-interaction','Interaction layer'],['layer-mechanism','Mechanism layer'],['layer-normative','Normative layer'],['temporal-records','Recorded evidence'],['discoveries','Findings']];
 return '<div class="research-restored research-showcase">'+editorialHero({kicker:'Research',title:'Theory and<br/><em>measurement.</em>',deck:'InteractEval evaluates interaction through an evidence-grounded world, its development over time, and each participant’s contribution.',aside:'<div class="research-summary"><span>Research</span><a href="#theory" data-research-section="theory">Three theoretical foundations ↘</a><a href="#framework" data-research-section="framework">Four-layer measurement architecture ↘</a><a href="#temporal-records" data-research-section="temporal-records">Recorded evidence ↘</a></div>'})+'<div class="article-shell">'+articleRail(sections,'Contents')+'<article class="article-body"><div class="showcase-content">'+researchReferenceMarkup+'</div><p class="reference-source">Theory: paper §2.1–2.4. Measurement architecture: §3.1–3.6. Figures illustrate definitions; controls demonstrate the stated rules, not additional experimental observations.</p>'+journalSection('temporal-records','03','Recorded evidence','Interaction records over time','Selected paper examples, not a new experiment.','<div id="research-records-body">'+researchRecordsPanel()+'</div>')+journalSection('discoveries','04','Findings','Experimental findings','Full-study results remain separate from individual illustrative cases.',researchFindingsPanel())+'<div class="research-exit-links"><a href="./index.html#models"><strong>Model results</strong><span>Full dashboard ↗</span></a><a href="./showcase.html"><strong>Case records</strong><span>Open Showcase ↗</span></a></div></article></div></div>';
}
function researchCascadeScores(raw){let z=1;return raw.map(r=>{const s=Math.min(r,z),row={r,z,s};z=s===0?0:s<0.6?s:z;return row;});}
function mountResearchShowcase(){
 const host=document.querySelector('.research-showcase');if(!host||host.dataset.mounted)return;host.dataset.mounted='true';
 const header=document.querySelector('.masthead');if(header){new ResizeObserver(()=>host.style.setProperty('--research-nav-offset',(header.getBoundingClientRect().height+20)+'px')).observe(header);}
 const cube=host.querySelector('#cube'),out=host.querySelector('#cellOut');
 ['functional','mixed','nonfunctional'].forEach(p=>{
  const slab=document.createElement('div');slab.className='slab';const h=document.createElement('h5');h.textContent=p;slab.append(h);
  const grid=document.createElement('div');grid.className='g';
  ['sufficient','partial','insufficient'].forEach(info=>['realistic','stylized','science-fictional'].forEach(world=>{
   const b=document.createElement('button');b.type='button';b.className='cell';b.textContent='30';const msg='Purpose: '+p+' · Information: '+info+' · Realism: '+world+' · 30 cases.';b.setAttribute('aria-label',msg);b.setAttribute('aria-pressed','false');
   const select=()=>{cube.querySelectorAll('button').forEach(el=>el.setAttribute('aria-pressed',String(el===b)));out.textContent=msg;};b.addEventListener('click',select);b.addEventListener('focus',select);grid.append(b);
  }));slab.append(grid);cube.append(slab);
 });
 const rows=host.querySelector('#rubRows'),verdict=host.querySelector('#rubVerdict');
 const names=['Goal preservation','Information uptake','State progression','Contextual expression','Proactive agency','Long-horizon coherence'],raw=[1,0.6,0.4,1,1,1],grades=[0,0.4,0.6,1];
 function update(){
  const scores=researchCascadeScores(raw),block=scores.findIndex(d=>d.s<0.6);
  rows.innerHTML=scores.map((d,i)=>'<div class="lv'+(d.s<d.r?' cap':'')+(i===block?' blk':'')+'"><div class="id">L'+(i+1)+'</div><div class="nm">'+names[i]+'<small>'+['Passive execution','Responsive adaptation','Active adaptation'][Math.floor(i/2)]+'</small></div><div class="seg" role="group" aria-label="Raw grade for L'+(i+1)+'">'+grades.map(g=>'<button type="button" data-grade="'+g+'" data-level="'+i+'" aria-pressed="'+(raw[i]===g)+'" class="'+(raw[i]===g?'on':'')+'">'+g+'</button>').join('')+'</div><div class="bar"><i style="width:'+d.s*100+'%"></i><u style="left:calc('+d.r*100+'% - 1px)"></u><em style="width:'+d.z*100+'%"></em></div><div class="sv">s = '+d.s.toFixed(1)+'</div></div>').join('');
  verdict.textContent=block<0?'Every level passes. No blocking dimension.':'Blocking dimension: L'+(block+1)+' '+names[block]+'. Plateau: '+(block===0?'none':'L'+block)+'. Higher reported scores cannot exceed the inherited ceiling. Raw grades remain unchanged.';
 }
 rows.addEventListener('click',event=>{const b=event.target.closest('[data-grade]');if(!b)return;const i=Number(b.dataset.level),g=Number(b.dataset.grade);raw[i]=g;update();rows.querySelector('[data-level="'+i+'"][data-grade="'+g+'"]').focus({preventScroll:true});});update();
 host.querySelectorAll('.chapter,.layer').forEach(el=>el.classList.add('article-section'));
 host.querySelectorAll('.showcase-content a[href^="#"]').forEach(a=>a.dataset.researchSection=a.getAttribute('href').slice(1));
 if(typeof researchObserver!=='undefined'&&researchObserver)host.querySelectorAll('.article-section').forEach(el=>researchObserver.observe(el));
}
document.addEventListener('DOMContentLoaded',()=>{const app=document.getElementById('app');if(!app)return;new MutationObserver(()=>mountResearchShowcase()).observe(app,{childList:true});mountResearchShowcase();});
